function statusFor(type,id,t=townId){if(type==='town')t=id;const plan=planAt(type,id,t),a=ann(type==='prompt'?id:type+':'+id),units=scopedReviewUnits(type,id,t),keys=new Set(units.map(u=>u.key)),colors=units.map(u=>unitStatus(u,type==='character'?plan:null));let relatedRed=false,relatedYellow=false;for(const p of Object.values(data.changePlans)){if(p.target.townId!==t||p.workflow==='implemented'||targetRecord(p.target)?.archived)continue;if(!unitsFor(p.target.type,p.target.id,t).some(u=>keys.has(u.key)))continue;if(p.intent==='REMOVE')relatedRed=true;if(p.intent==='UPDATE')relatedYellow=true}for(const [key,value] of Object.entries(data.annotations)){if(!value.flag&&!value.note)continue;const split=key.indexOf(':'),at=key.slice(0,split),aid=key.slice(split+1);if(!['town','location','area','character','element'].includes(at)||value.context?.townId&&value.context.townId!==t)continue;const record=targetRecord({townId:t,type:at,id:aid});if(!record||record.archived||!unitsFor(at,aid,t).some(u=>keys.has(u.key)))continue;if(value.flag&&value.critical)relatedRed=true;else relatedYellow=true}const color=plan?.intent==='REMOVE'&&plan.workflow!=='implemented'||a.flag&&a.critical||relatedRed||colors.includes('red')?'red':(colors.includes('amber')||testingAt(targetRecord({townId:t,type,id})?.contentRecordId||id,t)?.pending)?'amber':plan?.intent==='UPDATE'?'yellow':units.length&&colors.every(c=>c==='grey')||!units.length&&!plan?'grey':a.flag||a.note||relatedYellow||!units.length||colors.includes('yellow')||colors.includes('grey')?'yellow':'green';return {color,units,total:units.length,verified:units.filter(u=>['verified','inaccessible'].includes(u.testStatus)).length,final:units.filter(u=>(unitPlans(u)[0]||plan)?.intent==='FINAL').length,pending:colors.filter(c=>c==='yellow').length,critical:colors.filter(c=>c==='red').length}}
