function receiptAllowedRoots(request){const tIndex=data.towns.findIndex(t=>t.id===request.target.townId),t=data.towns[tIndex],prefix='/towns/'+tIndex,target=request.target,paths=[];if(target.type==='town')paths.push(prefix);if(target.type==='location'){paths.push(prefix+'/locations/'+t.locations.findIndex(l=>l.id===target.id));for(const id of targetRecord(target).areaIds)paths.push(prefix+'/areas/'+t.areas.findIndex(a=>a.id===id))}if(target.type==='area')paths.push(prefix+'/areas/'+t.areas.findIndex(a=>a.id===target.id));if(target.type==='character'){paths.push(prefix+'/characters/'+t.characters.findIndex(c=>c.id===target.id));const c=targetRecord(target);for(const id of new Set([c.identityId,...Object.values(c.identityByGender||{})].filter(Boolean)))paths.push('/characterNames/'+pointerPart(id));}for(const a of t.areas)for(const e of a.elements){const ep=prefix+'/areas/'+t.areas.indexOf(a)+'/elements/'+a.elements.indexOf(e);if(target.type==='element'&&e.id===target.id)paths.push(ep);if(target.type==='character'&&targetRecord(target).elementIds.includes(e.id)&&!t.characters.some(c=>c.id!==target.id&&c.elementIds.includes(e.id)))paths.push(ep);for(const p of e.points){if(!request.references.pointIds.includes(p.id))continue;const pp=ep+'/points/'+e.points.indexOf(p);if(target.type==='prompt'||target.type==='character'&&e.kind==='scene'&&request.sharedSceneHandling==='retain-others'){const blockIds=target.type==='prompt'?target.blockIds:reviewUnits().filter(u=>u.t.id===t.id&&u.e.id===e.id&&u.p.id===p.id&&u.turn.speakerKey===target.id).flatMap(u=>u.turn.entries.map(x=>x.blockId));for(const [i,b] of p.blocks.entries())if(blockIds.includes(b.id)||blockIds.includes(b.id+'-female'))paths.push(pp+'/blocks/'+i);if(target.type==='character')paths.push(pp+'/participantIds');}else paths.push(pp)}}for(const id of request.references.sourceIds)paths.push('/liveMappings/'+pointerPart(id));return paths.filter(p=>!p.endsWith('/-1'))}
