function refreshTileIndicators(){for(const tile of document.querySelectorAll('[data-tile-key]')){const key=tile.dataset.tileKey,index=key.indexOf(':'),type=key.slice(0,index),id=key.slice(index+1),t=tile.closest('[data-town-scope]')?.dataset.townScope||townId;tile.querySelector('.content-light')?.remove();tile.querySelector('.flag-mark')?.remove();const flagged=tileFlag(type,id,t);if(flagged.flag)tile.insertAdjacentHTML('beforeend',`<span class="flag-mark ${flagged.critical?'flag-critical':'flag-standard'}" aria-label="${flagged.critical?'Critical':'Standard'} Flag">⚑</span>`);tile.insertAdjacentHTML('beforeend',statusHTML(type,id,t));const tag=tile.querySelector('.tile-intent');if(tag)tag.innerHTML=intentHTML(type,id,t)}renderTimeline();}
function renderPreservingScroll(){const positions=[['maps',$('maps')?.scrollTop],['groups',$('groups')?.scrollTop]];const dialogue=document.querySelector('.conversation')?.scrollTop||0,message=$('message-scroll')?.scrollTop||0,conditions=document.querySelector('.conditions-pane')?.scrollTop||0,list=$('dialogue-options')?.scrollTop||0;render();for(const [id,value] of positions)if($(id))$(id).scrollTop=value||0;if(document.querySelector('.conversation'))document.querySelector('.conversation').scrollTop=dialogue;if($('message-scroll'))$('message-scroll').scrollTop=message;if(document.querySelector('.conditions-pane'))document.querySelector('.conditions-pane').scrollTop=conditions;if($('dialogue-options'))$('dialogue-options').scrollTop=list;}
function renderDialogueOptions(options){return `<h3 class="dialogue-list-title">Dialogue Entries</h3><div id="dialogue-options" class="dialogue-entry-list" role="group" aria-label="Dialogue Entries">${options.length?options.map(p=>`<button class="dialogue-option" data-dialogue-id="${esc(p.id)}" aria-pressed="${p.id===pointId}" title="${esc(sentenceCase(p.condition))}">${statusHTML('point',p.id)}<span class="dialogue-option-label">${esc(pointLabel(p))}</span><small>${esc(formatStages(p.elementName))}</small>${intentHTML('point',p.id)}</button>`).join(''):'<p class="muted">No documented dialogue at this stage.</p>'}</div>`}
let dialogueClickTimer=null;
function bindDialogueOptions(){for(const b of $('dialogue-options')?.querySelectorAll('[data-dialogue-id]')||[]){const select=()=>{flushNote();pointId=b.dataset.dialogueId;pageIndex=0;reviewEntryKey=null;scopeOverride=null;renderDialogue()};b.onclick=e=>{if(e.target.tagName==='INPUT')return;clearTimeout(dialogueClickTimer);if(e.detail===0)select();else dialogueClickTimer=setTimeout(select,230)};b.ondblclick=e=>{e.preventDefault();clearTimeout(dialogueClickTimer);const id=b.dataset.dialogueId;flushNote();pointId=id;pageIndex=0;reviewEntryKey=null;scopeOverride=null;renderDialogue(true);const selectedButton=[...$('dialogue-options').querySelectorAll('[data-dialogue-id]')].find(b=>b.dataset.dialogueId===id);beginRename(current(),selectedButton)}} }

function initPlanningUI(){$('decision-conflicts-open').onclick=showDecisionConflicts;$('decision-conflicts-close').onclick=()=>$('decision-conflict-dialog').close();$('setting-intent').onchange=togglePlanningFields;$('setting-critical').onchange=()=>{if($('setting-critical').checked)$('setting-flag').checked=true};$('setting-flag').onchange=()=>{if(!$('setting-flag').checked)$('setting-critical').checked=false};$('history-open').onclick=showHistory;$('history-open-flags').onclick=showHistory;$('history-close').onclick=()=>$('history-dialog').close();$('receipt-import').onchange=async()=>{const file=$('receipt-import').files[0];if(!file)return;try{const receipt=JSON.parse(await file.text());await inspectReceipt(receipt);receiptDraft=receipt;$('receipt-preview').textContent=JSON.stringify(receipt,null,2);$('receipt-status').textContent='Baseline and target scope validated. Review the implementation before applying it.';$('receipt-apply').disabled=false;$('receipt-dialog').showModal()}catch(e){$('data-status').textContent='Receipt rejected: '+e.message;$('data-status').className='error'}finally{$('receipt-import').value=''}};$('receipt-close').onclick=()=>$('receipt-dialog').close();$('receipt-apply').onclick=async()=>{try{await applyReceipt(receiptDraft);$('receipt-dialog').close();$('data-status').textContent='Implementation reconciled. Save Changes to commit; affected prompts require tester validation.'}catch(e){$('receipt-status').textContent=e.message;$('receipt-apply').disabled=true}}}



let reviewMenuEntries=[];
