function dialogueDecisionConflicts(key){return Object.values(data.decisionConflicts||{}).filter(c=>c.promptKey===key&&c.status==='pending')}
function migrateDialogueDecisions(){if(!data.legacyChangePlans)data.legacyChangePlans={};if(!data.decisionConflicts)data.decisionConflicts={};const legacy=Object.entries(data.changePlans).filter(([k,p])=>p.target.type==='point'||p.target.type==='element'&&targetRecord(p.target)?.points.some(p=>p.blocks.some(b=>b.type==='dialogue')));if(!legacy.length)return false;
 commitChange('Migrate Event Decisions to Speaker Prompts',()=>{for(const [key,old] of legacy){data.legacyChangePlans[old.id]=structuredClone(old);for(const u of unitsFor(old.target.type,old.target.id,old.target.townId)){const target={townId:u.t.id,type:'prompt',id:u.key,pointId:u.p.id,speakerKey:u.turn.speakerKey,passageKeys:u.turn.entries.map(x=>x.key),blockIds:[...new Set(u.turn.entries.map(x=>x.blockId))]},newKey=targetKey('prompt',u.key,u.t.id),existing=data.changePlans[newKey],candidate={...structuredClone(old),id:'plan-'+crypto.randomUUID(),target,label:u.turn.speakerLabel+' · '+pointLabel(u.p),migratedFromPlanId:old.id,sharedSceneHandling:'instructions'};if(existing&&(existing.intent!==old.intent||existing.instructions!==old.instructions||existing.proposedDialogue!==old.proposedDialogue)){const id=old.id+'|'+u.key;data.decisionConflicts[id]={id,promptKey:u.key,target,existing:structuredClone(existing),candidate,status:'pending'};}else if(!existing)data.changePlans[newKey]=candidate;}delete data.changePlans[key]}},{pointIds:[...new Set(legacy.flatMap(([k,p])=>unitsFor(p.target.type,p.target.id,p.target.townId).map(u=>u.p.id)))]});return true;
}
function resolveDialogueDecision(id,choice){const conflict=data.decisionConflicts[id];if(!conflict||conflict.status!=='pending')return;commitChange('Resolve Prompt Decision Conflict',()=>{const key=targetKey('prompt',conflict.promptKey,conflict.target.townId),current=data.changePlans[key];if(JSON.stringify(current)!==JSON.stringify(conflict.existing))throw Error('The prompt decision changed. Open its settings to resolve this conflict with current instructions.');data.changePlans[key]=structuredClone(choice==='event'?conflict.candidate:conflict.existing);conflict.status='resolved';conflict.choice=choice;conflict.resolvedAt=new Date().toISOString()},{target:conflict.target,pointIds:[conflict.target.pointId]});render();showDecisionConflicts()}
function showDecisionConflicts(){const list=Object.values(data.decisionConflicts||{}).filter(c=>c.status==='pending');$('decision-conflict-list').innerHTML=list.map((c,i)=>`<article class="history-entry"><h3>${esc(c.existing.label||c.promptKey)}</h3><p>Prompt: ${esc(c.existing.intent)} — ${esc(c.existing.instructions||'No instructions')}</p><p>Former Event: ${esc(c.candidate.intent)} — ${esc(c.candidate.instructions||'No instructions')}</p><div class="actions"><button data-conflict="${i}" data-choice="prompt">Keep Prompt Decision</button><button data-conflict="${i}" data-choice="event">Use Former Event Decision</button></div></article>`).join('')||'<p>No pending decision conflicts.</p>';$('decision-conflict-list').querySelectorAll('[data-conflict]').forEach(b=>b.onclick=()=>{try{resolveDialogueDecision(list[Number(b.dataset.conflict)].id,b.dataset.choice)}catch(e){$('decision-conflict-message').textContent=e.message}});if(!$('decision-conflict-dialog').open)$('decision-conflict-dialog').showModal()}

const STANDARD_NOTES_SUITE=Object.freeze({name:'Standard Notes Suite',version:1,flags:['Standard','Critical'],statuses:['FINAL','UPDATE','REMOVE'],unset:'grey',verificationScope:'Speaker prompt only'});
function standardFlagControls(prefix,a,label='Flag Prompt'){const button=prefix==='entry'?'entry-flag':prefix+'-flag-button',picker=prefix==='entry'?'flag-severity-picker':prefix+'-flag-severity-picker';return `<button id="${button}" class="suite-flag-button ${a.flag?(a.critical?'flag-critical':'flag-standard'):''}" aria-pressed="${!!a.flag}">⚑ ${a.flag?'Flagged':esc(label)}</button><div id="${picker}" class="flag-severity-picker hidden" role="group" aria-label="Flag Severity"><button id="${prefix==='entry'?'flag':prefix}-pick-standard" class="flag-standard">Standard</button><button id="${prefix==='entry'?'flag':prefix}-pick-critical" class="flag-critical">Critical</button></div>`}
function standardNoteButton(prefix,note){return `<button id="${prefix}-note-toggle">${note?'Edit Note':'Add Note'}</button>`}
function standardNoteEditor(prefix,note,label){const input=prefix==='setting'?'setting-note':prefix+'-note-text';return `<div class="entry-note hidden" id="${prefix}-note-editor"><label style="flex:1">${esc(label)}<textarea id="${input}" rows="3">${esc(note||'')}</textarea></label><button id="${prefix}-note-apply">Apply Note</button></div>`}
function standardStatusButtons(prefix,intent,critical){return `<div class="status-buttons ${STANDARD_NOTES_SUITE.statuses.includes(intent)?'has-selection':''}">${STANDARD_NOTES_SUITE.statuses.map(value=>`<button data-${prefix}-intent="${value}" class="status-choice ${value.toLowerCase()} ${value==='UPDATE'&&critical?'critical-update':''}" aria-pressed="${intent===value}">${value}</button>`).join('')}</div>`}
function bindStandardFlagControls(prefix,read,write,refresh,before=()=>{}){const button=prefix==='entry'?'entry-flag':prefix+'-flag-button',picker=prefix==='entry'?'flag-severity-picker':prefix+'-flag-severity-picker';$(button).onclick=()=>{before();if(read().flag){write({flag:false,critical:false});refresh()}else $(picker).classList.toggle('hidden')};for(const [severity,critical] of [['standard',false],['critical',true]])$((prefix==='entry'?'flag':prefix)+'-pick-'+severity).onclick=()=>{before();write({flag:true,critical});refresh()}}
function ensureSettingSuiteMarkup(){$('setting-feedback-controls').before($('npc-name-fields'));$('change-instructions-fields').after($('setting-suite-note-host'));$('setting-suite-note-host').innerHTML=standardNoteEditor('setting','','Note for this item')}
function settingAnnotationKey(){return settingsTarget.type==='prompt'?settingsTarget.id:settingsTarget.key}
