function syncSettingSuite(){const a=ann(settingAnnotationKey());$('setting-flag').checked=!!a.flag;$('setting-critical').checked=!!a.critical;$('setting-feedback-controls').innerHTML=standardFlagControls('setting',a,settingsTarget.type==='prompt'?'Flag Prompt':'Flag Item')+standardNoteButton('setting',a.note)+`<span class="note-indicator">${esc(a.note||'')}</span>`;$('setting-status-buttons').innerHTML=standardStatusButtons('setting',$('setting-intent').value,tileFlag(settingsTarget.type,settingsTarget.id,planningTarget.townId).critical);bindStandardFlagControls('setting',()=>ann(settingAnnotationKey()),saveSettingFeedback,syncSettingSuite,flushSettingDescription);$('setting-note-toggle').onclick=()=>{$('setting-note-editor').classList.toggle('hidden');if(!$('setting-note-editor').classList.contains('hidden')){$('setting-note').value=ann(settingAnnotationKey()).note||'';$('setting-note').focus()}};$('setting-note').oninput=markDirty;$('setting-note').onchange=flushSettingNote;$('setting-note-apply').onclick=()=>{saveSettingFeedback({note:$('setting-note').value});$('setting-note-editor').classList.add('hidden')};$('setting-status-buttons').querySelectorAll('[data-setting-intent]').forEach(b=>b.onclick=()=>chooseSettingIntent(b.dataset.settingIntent));}
function chooseSettingIntent(value){flushSettingDescription();const target=planningTarget,key=targetKey(target.type,target.id,target.townId),existing=data.changePlans[key],intent=existing?.intent===value?'':value;commitChange('Set Item Change Status',()=>{if(!intent){delete data.changePlans[key];}else data.changePlans[key]={...existing,id:existing?.id||'plan-'+crypto.randomUUID(),target:structuredClone(target),label:settingsTarget.label,intent,instructions:existing?.instructions||'',proposedDialogue:existing?.proposedDialogue||'',sharedSceneHandling:'instructions',workflow:['UPDATE','REMOVE'].includes(intent)&&!existing?.instructions?.trim()?'draft':'planned',createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};},{target});$('setting-intent').value=intent;$('setting-instructions').value=data.changePlans[key]?.instructions||'';$('setting-proposed').value=data.changePlans[key]?.proposedDialogue||'';togglePlanningFields();syncSettingSuite();renderDialogue(true);refreshTileIndicators()}
function flushSettingDescription(){if(!$('settings-dialog').open||settingsTarget?.promptOnly)return;const target=planningTarget,key=targetKey(target.type,target.id,target.townId),plan=data.changePlans[key];if(!plan||!['UPDATE','REMOVE'].includes(plan.intent))return;const instructions=$('setting-instructions').value,proposed=$('setting-proposed').value;if(plan.instructions===instructions&&plan.proposedDialogue===proposed)return;commitChange('Edit Item Change Description',()=>{plan.instructions=instructions;plan.proposedDialogue=proposed;plan.workflow=instructions.trim()?'planned':'draft';plan.updatedAt=new Date().toISOString()},{target});refreshTileIndicators()}
