const flushBeforeStandardSuite=flushNote;flushNote=function(){flushSettingDescription();flushSettingNote();flushBeforeStandardSuite()};

function effectivePromptPlan(p,turn){const key=promptAnnotationKey(p,turn),unit=unitsFor('prompt',key)[0];return planAt('prompt',key)|| (unit?unitPlans(unit)[0]:null)}
function inlinePromptStatus(p,turn){const plan=effectivePromptPlan(p,turn),intent=plan?.intent||'',own=planAt('prompt',promptAnnotationKey(p,turn));return `<fieldset class="prompt-decision"><legend>Change Status</legend>${standardStatusButtons('prompt',intent,tileFlag('prompt',promptAnnotationKey(p,turn)).critical)}</fieldset>`}
function inlinePromptDescription(p,turn){const plan=planAt('prompt',promptAnnotationKey(p,turn))||effectivePromptPlan(p,turn);if(!['UPDATE','REMOVE'].includes(plan?.intent))return '';const key=promptAnnotationKey(p,turn);return `<section class="prompt-change-editor"><label>Change Description<textarea id="prompt-change-description" data-prompt-key="${esc(key)}" data-town-id="${esc(townId)}" data-target="${esc(JSON.stringify(makeTarget('prompt',key,{pointId:p.id,turn})))}" data-initial-instructions="${esc(plan.instructions||'')}" data-initial-proposed="${esc(plan.proposedDialogue||'')}" data-intent="${plan.intent}" data-label="${esc(turn.speakerLabel+' · '+pointLabel(p))}" rows="3" placeholder="Describe the ${plan.intent==='REMOVE'?'removal':'changes'} for this prompt.">${esc(plan.instructions||'')}</textarea></label><details><summary>Proposed Dialogue</summary><textarea id="prompt-proposed-dialogue" rows="3">${esc(plan.proposedDialogue||'')}</textarea></details><button id="prompt-change-apply">Apply Changes</button><small id="prompt-change-hint">${plan.workflow==='draft'?'Add a description before this ticket can be sent for implementation.':'Changes are included in Save Changes.'}</small></section>`}
