function sourceArea(e){return town().areas.find(a=>a.elements.some(x=>x.id===e.id))}
function encounterAreaIds(e){if(Array.isArray(e.encounterAreaIds))return e.encounterAreaIds;if(town().id==='new-bark-town'){const shared={'shared-0':['61'],'shared-1':['60'],'shared-2':['60'],'shared-3':['60','61','63']};if(shared[e.id])return shared[e.id]}const a=sourceArea(e);return a?[a.id]:[]}
