function validate(d){if(d?.version!==2||!Array.isArray(d.towns)||!d.towns.length||!Array.isArray(d.stages)||d.stages.length>256||!d.annotations||typeof d.annotations!=='object'||Array.isArray(d.annotations))throw Error('Expected NPCDex version 2 with towns, stages and annotations.');globalThis.romdexTimelines.validateSnapshot(d);const check=(arr,type)=>{if(!Array.isArray(arr))throw Error('Missing '+type+' collection.');const ids=new Set();for(const o of arr){if(typeof o.id!=='string'||!o.id||ids.has(o.id))throw Error('Invalid or duplicate '+type+' ID.');ids.add(o.id);if(o.image&&(!/^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/=\s]+$/.test(o.image.dataUrl||'')||o.image.dataUrl.length>15*1024*1024))throw Error('Images must be embedded PNG, JPEG, WebP or GIF data URLs (maximum 10 MB).');if(o.gender&&!['both','male','female'].includes(o.gender))throw Error('Invalid gender filter.');}return ids};if(d.characterImages){if(typeof d.characterImages!=='object'||Array.isArray(d.characterImages))throw Error('Invalid shared character image registry.');check(Object.entries(d.characterImages).map(([id,image])=>({id,image})),'shared image')}for(const t of d.towns)for(const c of t.characters){if(c.regionalImages)check(Object.entries(c.regionalImages).filter(([id,image])=>image!==null).map(([id,image])=>({id,image})),'regional image')}validatePlanning(d);check(d.towns,'town');check(d.stages,'stage');for(const t of d.towns){const known=new Set(['all',...globalThis.romdexTimelines.snapshotStages(d,t).map(s=>s.id)]);if(typeof t.name!=='string')throw Error('Town needs a name.');const areaIds=check(t.areas,'area');check(t.locations,'location');check(t.characters,'character');const elementIds=new Set(),pointIds=new Set(),blockIds=new Set();for(const a of t.areas){if(typeof a.name!=='string')throw Error('Area needs a name.');check(a.elements,'element');for(const e of a.elements){if(elementIds.has(e.id)||typeof e.name!=='string')throw Error('Duplicate element ID or missing name.');elementIds.add(e.id);check(e.points,'point');for(const p of e.points){if(pointIds.has(p.id)||typeof p.condition!=='string'||!Array.isArray(p.stages)||p.stages.some(s=>!known.has(s))||!Array.isArray(p.ids)||p.ids.some(id=>typeof id!=='string')||!Array.isArray(p.evidence))throw Error('Invalid dialogue point.');pointIds.add(p.id);check(p.blocks,'block');for(const b of p.blocks){if(blockIds.has(b.id)||!['dialogue','note'].includes(b.type)||typeof b.text!=='string')throw Error('Invalid dialogue block.');blockIds.add(b.id);}}}}for(const l of t.locations){if(typeof l.name!=='string'||!Array.isArray(l.areaIds)||l.areaIds.some(id=>!areaIds.has(id)))throw Error('Location references an unknown area.');}for(const c of t.characters){if(typeof c.name!=='string'||!Array.isArray(c.elementIds)||!Array.isArray(c.sceneIds)||[...c.elementIds,...c.sceneIds].some(id=>!elementIds.has(id)))throw Error('Character references an unknown element or scene.');}}for(const a of Object.values(d.annotations)){if(typeof a.note!=='string'||typeof a.flag!=='boolean'||(a.scope&&!['passage','prompt'].includes(a.scope))||(a.testStatus&&!['unreviewed','verified','inaccessible'].includes(a.testStatus)))throw Error('Invalid flag or note.');}}
